const pending=new Map(),registered=new Set(),validIds=new Set(),questionIds=new Map();
for(const entry of catalog){const chapter=C.chapters.find(c=>c.id===entry.chapter);chapter.sections=entry.sections;chapter.questionCount=entry.questions;chapter.expanded=[];for(const s of chapter.sections)for(const c of s.concepts){validIds.add(c.id);questionIds.set(c.id,new Set(c.questions));}}
C.register=function(id,rows){
 const c=C.chapters.find(c=>c.id===Number(id));if(!c||registered.has(c.id))return;
 c.expanded=rows.map(r=>{
  const s=c.sections.find(s=>s.id===r[2]);
  return {id:r[0],concept:r[1],chapter:c.id,section:r[2],heading:r[3],level:r[4],group:r[2],kind:'answer',prompt:r[5],answer:r[0]+'-a',
   options:[r[6],...r[7]].map((label,i)=>({id:r[0]+'-'+String.fromCharCode(97+i),label})),explanation:r[8],hint:r[9],source:s.source+(r[10]?'#'+r[10]:''),sectionSource:s.source,
   definitionSource:r[4]==='foundations'?C.book+c.id+'-key-terms':null,topic:r[6]};
 });registered.add(c.id);
};
C.loaded=id=>registered.has(Number(id));
C.ensureChapter=function(id){if(typeof module==='object'&&module.exports&&!C.loaded(id))require('./content/chapter-'+String(id).padStart(2,'0')+'.js');};
C.load=function(id){
 id=Number(id);if(C.loaded(id))return Promise.resolve();
 if(typeof module==='object'&&module.exports){C.ensureChapter(id);return Promise.resolve();}
 if(pending.has(id))return pending.get(id);
 const promise=new Promise((resolve,reject)=>{
  const script=document.createElement('script');script.src='content/chapter-'+String(id).padStart(2,'0')+'.js?v=2.1.0';
  const timer=setTimeout(()=>{script.remove();pending.delete(id);reject(Error('The chapter questions did not load. Check your connection or keep the content folder beside index.html.'));},15000);
  script.onload=()=>{clearTimeout(timer);if(C.loaded(id))resolve();else{pending.delete(id);reject(Error('This chapter question file is incomplete.'));}};
  script.onerror=()=>{clearTimeout(timer);script.remove();pending.delete(id);reject(Error('The chapter questions could not load. Try again or use the complete Desktop copy.'));};document.head.appendChild(script);
 });pending.set(id,promise);return promise;
};
C.validConcept=id=>validIds.has(id)||C.chapters.some(c=>c.concepts.some(f=>f.id===id)||id===`c${c.id}-route`);
C.validQuestion=(id,q)=>questionIds.get(id)?.has(q)||(/^c\d+-/.test(id)&&q.startsWith(id+'-'));
C.scope=function(chapterId,scope='all'){
 const c=C.chapters.find(c=>c.id===Number(chapterId));return c?c.sections.filter(s=>scope==='all'||s.id===scope):[];
};
C.summary={chapters:28,numberedSections:169,introductions:28,questions:catalog.reduce((n,c)=>n+c.questions,0),objectives:606};
C.version="2.1.0";
return C;
